{"catalogue_version":"2026.09.16","doc_path":"/docs/hiecm/v3/api/m2/endpoints/m2-post-v3-token-generate-token","operation_id":"m2_post_v3_token_generate_token","spec":{"description":"This API endpoint is used to generate a link token which will be valid for 6 months.. This token can be utilized for Health Information Provider (HIP) Initiated Linking, enabling HIPs to securely link patient health records to their ABHA (Ayushman Bharat Health Account) address. The generated token ensures that the linking process is authenticated and authorized, maintaining the integrity and security of health information exchange. This functionality is crucial for facilitating seamless and efficient linking of health records within the healthcare ecosystem.<ol type='a'><li><b>Authorization:</b> We are passing the access-token in the authorization [Example: Bearer  eyJhbGciOiJSUzI1NiIsInR5cCIgOiAiSldUIiwia2lkIiA6ICJBbFJiNVd]</li></ol>","operationId":"m2_post_v3_token_generate_token","parameters":[{"description":"Unique UUID for track the end to end request transaction","example":"18235d89-cb13-479d-ad71-7a57d5f669a8","in":"header","name":"REQUEST-ID","required":true,"schema":{"type":"string"}},{"description":"Actual time of the request was initiated, ISO 8601 represents date and time by starting with the year, followed by the month, the day, the hour, the minutes, seconds and milliseconds","example":"2022-10-06T15:10:00.587Z","in":"header","name":"TIMESTAMP","required":true,"schema":{"type":"string"}},{"description":"Suffix of the consent manager to which the request was intended","example":"sbx","in":"header","name":"X-CM-ID","required":true,"schema":{"type":"string"}},{"description":"Identifier of the health information provider to which the request was intended","example":"IN2810014366","in":"header","name":"X-HIP-ID","required":true,"schema":{"type":"string"}}],"requestBody":{"content":{"application/json":{"schema":{"description":"In the request body, either 'abhaNumber' or 'abhaAddress' must be included, with atleast one being mandatory based on the patient profile.","properties":{"abhaAddress":{"description":"abhaAddress of the user/patient. Allows alpha numeric character and special characters like ^[a-zA-Z0-9][a-zA-Z0-9_.]+[a-zA-Z0-9]@(abdm|sbx)$","example":"<ABHA_ADDRESS>","nullable":true,"type":"string"},"abhaNumber":{"description":"it can be null if abhaNumber is not linked with abhaAddress. Allows numeric character like ^\\d{14}$","example":12345678901234,"nullable":true,"type":"number"},"gender":{"description":"Allows M, F, O, D, T, U as a input","example":"M","type":"string"},"name":{"description":"Only alphabets and special characters like ',.- are allowed like ^[a-zA-Z]+(([',. -][a-zA-Z ])?[a-zA-Z]*)*$","example":"first_name + middle_name + last_name","type":"string"},"yearOfBirth":{"description":"Year of birth must be 4 digit, ranging between 1900 and 2200","example":9999,"type":"number"}},"required":["abhaAddress","name","gender","yearOfBirth"],"type":"object"}}},"required":true},"responses":{"202":{"description":"Accepted"},"400":{"content":{"application/json":{"schema":{"properties":{"error":{"description":"The error code and message, if any occurred.","properties":{"code":{"description":"ABDM-1035 - Invalid HIP ID. May be returned either bare (`ABDM-1035`) or with a trailing \": \" separator (`ABDM-1035: `); match on the code itself and tolerate the separator.","example":"ABDM-1035","pattern":"^(ABDM-\\d{4}|\\d{3,6})(: )?$","type":"string"},"message":{"example":"Invalid HIP ID","type":"string"}},"required":["code","message"],"type":"object"}},"type":"object"}}},"description":"Bad Request"},"401":{"content":{"application/json":{"schema":{"properties":{"code":{"description":"900902 - Unauthorized. May be returned either bare or with a trailing \": \" separator; match on the code itself and tolerate the separator.","example":"900902","pattern":"^(ABDM-\\d{4}|\\d{3,6})(: )?$","type":"string"},"description":{"example":"Invalid Credentials. Make sure your API invocation call has a header: 'Authorization : Bearer ACCESS_TOKEN' or 'Authorization : Basic ACCESS_TOKEN' or 'apikey: API_KEY'","type":"string"},"message":{"example":"Unauthorized","type":"string"}},"type":"object"}}},"description":"Unauthorized"},"403":{"content":{"text/plain":{"schema":{"example":"Access Denied","type":"string"}}},"description":"Forbidden"},"404":{"description":"server cannot find the requested resource"},"500":{"content":{"application/json":{"schema":{"properties":{"code":{"description":"900900 - Unclassified Authentication Failure. May be returned either bare or with a trailing \": \" separator; match on the code itself and tolerate the separator.","example":"900900","pattern":"^(ABDM-\\d{4}|\\d{3,6})(: )?$","type":"string"},"description":{"example":"Access failure for API: /hiecm/api/v3, version: v3 status: (900900) - Unclassified Authentication Failure","type":"string"},"message":{"example":"Unclassified Authentication Failure","type":"string"}},"type":"object"}}},"description":"Internal Server Error"},"503":{"content":{"application/json":{"schema":{"properties":{"code":{"description":"ABDM-1024 - Dependent service unavailable. May be returned either bare (`ABDM-1024`) or with a trailing \": \" separator (`ABDM-1024: `); match on the code itself and tolerate the separator.","example":"ABDM-1024","pattern":"^(ABDM-\\d{4}|\\d{3,6})(: )?$","type":"string"},"message":{"example":"Dependent service unavailable","type":"string"}},"required":["code","message"],"type":"object"}}},"description":"Service Unavailable"}},"security":[{"bearerAuth":[]}],"summary":"API used to generate link token to link the health records","tags":["abdm-link-token-hip"],"x-abdm-nha-operation-id":"abdm-link-token 1"}}
